---time 单位：秒
---用于开宝箱转换时间与钻石比例
function Constant.TimeToDiamondCost (time)
    local cost = 0;
    if (time <= 60) then
        cost = 0;
    elseif (time <= 60 * 60) then
        cost = math.floor((time - 60) / ((3600 - 60) / 19) + 1);
    elseif (time <= 60 * 60 * 24) then
        cost = math.floor((time - 3600) / ((86400 - 3600) / 240) + 20);
    else
        cost = math.floor((time - 86400) / ((604800 - 86400) / 740) + 260);
    end
    return cost * 2;
end

function Constant.ColorByteToFloat(r, g, b, a)
    if (a == nil) then
        a = 255;
    end
    return Color.New(r / 255, g / 255, b / 255, a / 255);
end
